import { ID_PATTERNS } from "@antireverse/protocol";
import Link from "next/link";
import { notFound, redirect } from "next/navigation";
import { AppShell } from "@/components/app-shell.tsx";
import { PageHeader } from "@/components/page-header.tsx";
import { TargetView } from "@/features/prove/target-detail.tsx";
import { getCurrentRulesOfEngagement, getTarget, NotFoundError, UnauthorizedError } from "@/lib/api.ts";
import { requireSession } from "@/lib/guard.ts";
import { ROUTES } from "@/lib/routes.ts";
import { t } from "@/lib/t.ts";

// The route types of `.next/types` are generated by `next typegen`, which this slice does not run; the props are
// written out instead of `PageProps<"/prove/targets/[targetId]">`.
interface TargetPageProps {
  params: Promise<{ targetId: string }>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}

// `/prove/targets/[targetId]?confirm=remove` — one host: its status, the two ways to prove it, Verify and Remove.
// The removal step is opened by the address and holds the only form that can remove; a host in the current scope
// of the Rules of Engagement offers no removal.
export default async function TargetPage({ params, searchParams }: TargetPageProps) {
  const { key, organization } = await requireSession();
  const { targetId } = await params;
  if (!ID_PATTERNS.tgt.test(targetId)) notFound();
  let loaded: [Awaited<ReturnType<typeof getTarget>>, Awaited<ReturnType<typeof getCurrentRulesOfEngagement>>];
  try {
    loaded = await Promise.all([getTarget(key, targetId), getCurrentRulesOfEngagement(key)]);
  } catch (error) {
    // An unknown target and a target of another Organization look the same.
    if (error instanceof NotFoundError) notFound();
    if (error instanceof UnauthorizedError) redirect(ROUTES.signInExpired);
    throw error;
  }
  const [{ target, verification }, { version }] = loaded;
  const inScope = version?.scope.includes(target.id) ?? false;
  const { confirm } = await searchParams;

  return (
    <AppShell organization={organization} current="targets">
      <PageHeader eyebrow={<Link href={ROUTES.targets}>{t("target.back")}</Link>} title={target.host} />
      <TargetView
        target={target}
        verification={verification}
        inScope={inScope}
        confirmRemove={confirm === "remove" && !inScope}
      />
    </AppShell>
  );
}
